<script lang="ts">import {page} from '$app/stores';import {goto} from '$app/navigation';import Heading from '$lib/components/Heading.svelte';import Icon from '$lib/components/Icon.svelte';import {workspace} from '$lib/stores/workspace';import {createWordPress} from '$lib/websites/store';import {validateWebsite,validateSetup,websiteSlug,type WebsiteSetup,type WebsiteMode,type Backup} from '$lib/websites/model.js';let step=1,name='',domain='',change=false,sample=false,archive:Backup|null=null,sql:Backup|null=null,error='',busy=false;let review:WebsiteSetup|null=null;let mode:WebsiteMode;let lastMode:WebsiteMode|undefined;
 $: mode=$page.url.searchParams.get('mode')==='migrate'?'migrate':'install';$: if(mode!==lastMode){lastMode=mode;step=1;review=null;error='';}
 $: address=domain||(websiteSlug(name)||'your-website')+'.drevanta.example';$: available=$workspace.domains.filter(d=>!d.project&&!d.system);
 function pick(e:Event,kind:'archive'|'sql'){const f=(e.currentTarget as HTMLInputElement).files?.[0];const metadata=f?{name:f.name,size:f.size}:null;if(kind==='archive')archive=metadata;else sql=metadata;}
 function next(){try{validateWebsite(name,domain,$workspace);review=validateSetup({mode,sample,archive,sql});error='';step=2;}catch(e){error=e instanceof Error?e.message:'Review failed.';}}
 async function confirm(){if(!review||busy)return;busy=true;try{error='';const id=createWordPress(name,domain,review);await goto('/projects/'+id+'/overview');}catch(e){error=e instanceof Error?e.message:'Could not create website.';}finally{busy=false;}}
</script>
<Heading title={mode==='migrate'?'Migrate WordPress':'Install WordPress'} subtitle={step===1?'Step 1 of 2 · Configure your website on this server.':'Step 2 of 2 · Review WordPress setup.'}/><div class="stack" style="max-width:780px">{#if step===1}<form class="card stack" on:submit|preventDefault={next}><label class="field">Website name<input required maxlength="80" bind:value={name} placeholder="Business website"/></label><div class="well stack"><div class="row between wrap"><strong>Website address</strong><button class="btn ghost small" type="button" on:click={()=>change=!change}>{change?'Close':'Change'}</button></div><strong class="native-path">{address}</strong><small>{domain?'Custom domain · DNS verification required':'Automatically assigned · connect your own domain later.'}</small>{#if change}<label class="field">Available domain<select bind:value={domain}><option value="">Automatic address</option>{#each available as d}<option value={d.id}>{d.name}</option>{/each}</select></label><a class="link-btn" href="/domains">Add a domain in Domains</a>{/if}</div>{#if mode==='migrate'}<label class="field">Website backup (.zip)<input type="file" accept=".zip" disabled={sample} on:change={(e)=>pick(e,'archive')}/>{#if archive&&!sample}<small>{archive.name} · {archive.size} bytes</small>{/if}</label><label class="field">Database export (.sql or .sql.gz)<input type="file" accept=".sql,.gz" disabled={sample} on:change={(e)=>pick(e,'sql')}/>{#if sql&&!sample}<small>{sql.name} · {sql.size} bytes</small>{/if}</label><label class="check"><input type="checkbox" bind:checked={sample}/> Use sample backup and database export</label><div class="callout"><strong>Migration safety</strong><p>Both files and database are needed. Real migration requires compatibility checks, secure restore and a verified preview before DNS is switched. Only file names and sizes are recorded here; contents are not read or uploaded.</p></div>{:else}<div class="well"><strong>Included in this setup</strong><p class="subtitle">WordPress · PHP · MySQL · persistent website storage. A private database and user will be prepared automatically. Real administrator credentials are configured securely by the future installer.</p></div>{/if}{#if error}<p class="error" role="alert">{error}</p>{/if}<div class="native-actions"><a class="btn secondary" href="/websites/new">Back</a><button class="btn primary" type="submit">Review setup <Icon name="Arrow"/></button></div></form>{:else if review}<section class="card stack"><h3>Review WordPress setup</h3><div class="summary-list">{#each [['Website',name],['Operation',review.mode==='migrate'?'Migrate existing website':'Fresh install'],['Database','MySQL · private by default'],['Website address',address],['Environment','This server (demo)']] as row}<div><span>{row[0]}</span><strong class="native-path">{row[1]}</strong></div>{/each}{#if review.mode==='migrate'}<div><span>Backup</span><strong>{review.sample?'Sample files':review.archive?.name+' + '+review.sql?.name}</strong></div>{/if}</div><div class="callout">This saves a sample project, linked database and website address. No WordPress installation, SQL restore, public DNS change or HTTPS provisioning occurs.</div>{#if error}<p class="error" role="alert">{error}</p>{/if}<div class="native-actions"><button class="btn secondary" disabled={busy} on:click={()=>{step=1;error='';}}>Back</button><button class="btn primary" disabled={busy} on:click={confirm}>{busy?'Saving…':'Simulate setup'}</button></div></section>{/if}</div>
